class Solution {long long cross(vector<int> a,vector<int> b,vector<int> c){return (1LL*b[0]-a[0])*(1LL*c[1]-a[1])-(1LL*b[1]-a[1])*(1LL*c[0]-a[0]);}public:vector<vector<int>> solve(vector<vector<int>> points){sort(points.begin(),points.end());points.erase(unique(points.begin(),points.end()),points.end());if(points.size()<2)return points;vector<vector<int>> lower,upper;for(auto v:points){while(lower.size()>1&&cross(lower[lower.size()-2],lower.back(),v)<=0)lower.pop_back();lower.push_back(v);}for(auto i=points.rbegin();i!=points.rend();++i){auto v=*i;while(upper.size()>1&&cross(upper[upper.size()-2],upper.back(),v)<=0)upper.pop_back();upper.push_back(v);}lower.pop_back();upper.pop_back();lower.insert(lower.end(),upper.begin(),upper.end());return lower;}};